    'A.5.27': { desc: 'Use knowledge gained from security incidents to reduce likelihood or impact of future incidents.', guidance: 'Conduct root cause analysis after each incident. Update controls based on findings. Track corrective actions to closure.', evidence: ['Root cause analysis reports', 'Corrective action register', 'Control improvement evidence'], sampleDoc: 'Post-Incident Review Template' },
    'A.5.28': { desc: 'Collect and preserve evidence for security incidents that may require legal action.', guidance: 'Define digital evidence collection procedure. Maintain chain of custody. Ensure forensic-ready logging.', evidence: ['Evidence collection procedure', 'Chain of custody forms', 'Forensic readiness policy'], sampleDoc: 'Digital Evidence Collection Procedure' },
    'A.5.29': { desc: 'Plan for information security during disruption and have processes to maintain security in adverse conditions.', guidance: 'Include security considerations in BCP/DR plans. Ensure backup systems maintain security controls. Test security during DR exercises.', evidence: ['BCP/DR plan with security section', 'DR test results', 'Security control continuity assessment'], sampleDoc: 'Information Security in BCP Template' },
    'A.5.30': { desc: 'Ensure ICT readiness for business continuity through planning, implementation, and testing.', guidance: 'Document ICT recovery objectives (RTO/RPO). Test system recovery. Verify backup integrity regularly.', evidence: ['ICT continuity plan', 'Recovery test reports', 'Backup verification records'], sampleDoc: 'ICT Continuity Plan Template' },
