// Generic guidance for frameworks without specific control details
export const GENERIC_GUIDANCE = {
  sampleDocs: ['Policy Document', 'Procedure Document', 'Risk Assessment', 'Evidence of Implementation', 'Audit Report'],
  guidance: 'Review the official framework documentation for this control. Document your implementation approach, gather evidence of implementation, and record the date of last review.',
  evidence: ['Implementation documentation', 'Evidence of control operation', 'Review records'],
};

export function getControlDetail(frameworkId, controlId) {
  const fwDetails = CONTROL_DETAILS[frameworkId];
  if (!fwDetails) return null;
  return fwDetails[controlId] || null;
}
